INSERT INTO medicines (id, organization_id, brand_name, generic_name, category, manufacturer, dosage_form, strength, active_ingredients, inactive_excipients, tablet_shape, tablet_color, score_line, coating_type, indications, dosage_instructions, warnings_and_precautions, side_effects, storage_conditions, schedule_type, voice_summary_en, voice_summary_hi, voice_summary_mr, status)
VALUES (3, 2, 'Azee 500', 'Azithromycin Tablets IP', 'Macrolide Antibiotic', 'Cipla Limited', 'Tablet', '500 mg', '[{"name": "Azithromycin Dihydrate IP equivalent to Azithromycin", "strength": "500", "unit": "mg", "purpose": "Macrolide Antibiotic"}]', '["Lactose Monohydrate", "Pregelatinized Starch", "Croscarmellose Sodium", "Magnesium Stearate", "Sodium Lauryl Sulfate", "Opadry White Coating"]', 'Capsule-shaped', 'White', 'Single score line', 'Film-coated', 'Treatment of chest infections, sinus infections, throat infections, skin infections and typhoid.', 'Take 1 tablet once daily, preferably 1 hour before or 2 hours after meals for 3 to 5 days.', 'Caution in patients with liver disorders or heart arrhythmia (QT prolongation).', 'Loose motions, stomach upset, nausea, headache.', 'Store below 25°C in a dry place. Protect from light.', 'Schedule H1', 'Azee 500 Azithromycin tablet. Take one tablet once daily on an empty stomach for three days. Do not stop midway.', 'एज़ी 500 एज़िथ्रोमाइसिन टैबलेट। दिन में एक बार खाली पेट 3 दिनों के लिए लें।', 'अझी 500 अझिथ्रोमायसिन गोळी. दिवसातून एकदा उपाशी पोटी 3 दिवस घ्या.', 'active')
ON CONFLICT (id) DO NOTHING;
