VALUES (10, 2, 'Montair LC', 'Montelukast Sodium and Levocetirizine Hydrochloride Tablets IP', 'Respiratory Antiallergic', 'Cipla Limited', 'Tablet', '10 mg + 5 mg', '[{"name": "Montelukast Sodium IP eq. to Montelukast", "strength": "10", "unit": "mg", "purpose": "Leukotriene Receptor Antagonist"}, {"name": "Levocetirizine Dihydrochloride IP", "strength": "5", "unit": "mg", "purpose": "Antihistamine"}]', '["Microcrystalline Cellulose", "Mannitol", "Crospovidone", "Red Iron Oxide", "Yellow Iron Oxide", "Titanium Dioxide"]', 'Round biconvex', 'Pale orange-pink', 'None', 'Film-coated', 'Treatment of allergic asthma, perennial allergic rhinitis, and chronic hives.', 'Take 1 tablet once daily in the evening or before bed.', 'Not an emergency rescue inhaler substitute for sudden acute asthma attacks.', 'Drowsiness, dry mouth, headache, vivid dreams.', 'Store in the original strip below 25°C. Protect from moisture.', 'Schedule H', 'Montair LC tablet for allergic cough and asthma symptoms. Take one tablet at bedtime.', 'मॉन्टेयर एलसी एलर्जी, खांसी और दमा के लक्षणों के लिए। रात को सोने से पहले एक गोली लें।', 'मॉन्टेअर एलसी ॲलर्जी आणि दम्याच्या त्रासासाठी गोळी. रात्री झोपताना एक गोळी घ्या.', 'active')
ON CONFLICT (id) DO NOTHING;
