VALUES (12, 1, 'Shelcal 500', 'Calcium with Vitamin D3 Tablets IP', 'Mineral & Vitamin Supplement', 'Torrent Pharmaceuticals', 'Tablet', '500 mg Elemental Calcium + 250 IU Vit D3', '[{"name": "Calcium Carbonate IP eq. to Elemental Calcium", "strength": "500", "unit": "mg", "purpose": "Bone Mineral Supplement"}, {"name": "Cholecalciferol IP (Vitamin D3)", "strength": "250", "unit": "IU", "purpose": "Calcium Absorption Promoter"}]', '["Povidone", "Purified Talc", "Magnesium Stearate", "Sodium Starch Glycolate", "Titanium Dioxide"]', 'Oval biconvex', 'White', 'None', 'Film-coated', 'Osteoporosis, calcium deficiency, bone strength during pregnancy and lactation.', 'Take 1 tablet daily after lunch or dinner with water.', 'Do not take concurrently with iron supplements; maintain a 2-hour gap.', 'Constipation, bloating, gas.', 'Store below 30°C in a dry place.', 'OTC', 'Shelcal 500 Calcium and Vitamin D3 tablet for bone strength. Take one tablet daily after food.', 'शेलकल 500 हड्डियों की मजबूती के लिए कैल्शियम और विटामिन डी। रोजाना दोपहर या रात के खाने के बाद लें।', 'शेलकॅल 500 हाडांच्या मजबुतीसाठी कॅल्शियम आणि व्हिटॅमिन डी गोळी. जेवणानंतर रोज एक गोळी घ्या.', 'active')
ON CONFLICT (id) DO NOTHING;
